# seq_trigger.tsm: trigger on the 4th rising edge of 'req' that is not followed by 'ack' within the state
state wait_req:
  if (req == 1'bR) then
    increment_counter $counter0;
    goto wait_ack;
  endif
state wait_ack:
  if (ack == 1'b1) then
    goto wait_req;
  elseif ($counter0 == 16'u4) then
    trigger;
  else
    goto wait_ack;
  endif
